#!/usr/bin/env python3
"""Read source identifiers, never .env files or environment variable values."""
from pathlib import Path
import collections,datetime,json,re,subprocess

ROOT=Path('/Users/bao/taskbar-hero-qa');OUT=ROOT/'reports/v4-qa/Q2';OUT.mkdir(parents=True,exist_ok=True)
book=(ROOT/'reports/v4-ship/USER-DEPLOY-VI.md').read_text()
files=subprocess.check_output(['git','ls-files','-z'],cwd=ROOT).decode().split('\0')
patterns=[re.compile(r'(?:process|import\.meta)\.env\.([A-Z][A-Z0-9_]*)'),re.compile(r'(?:process|import\.meta)\.env\[[\'\"]([A-Z][A-Z0-9_]*)[\'\"]\]'),re.compile(r'Deno\.env\.get\([\'\"]([A-Z][A-Z0-9_]*)[\'\"]\)')]
patterns.append(re.compile(r'\b(?:env|localPort)\([\'\"]([A-Z][A-Z0-9_]*)[\'\"]'))
names=collections.defaultdict(list);dynamic=[]
for name in files:
    if not name.startswith(('apps/web/src/','api/','apps/web/api/','packages/','supabase/functions/','tools/chain/','scripts/')):continue
    if not name.endswith(('.js','.ts','.tsx','.mjs','.cjs')) or re.search(r'\.(test|spec)\.',name):continue
    path=ROOT/name
    if not path.is_file():continue
    text=path.read_text(errors='replace')
    for no,line in enumerate(text.splitlines(),1):
        for pattern in patterns:
            for match in pattern.finditer(line):names[match.group(1)].append(f'{name}:{no}')
        if re.search(r'(?:process|import\.meta)\.env\[[^\'\"]|Deno\.env\.get\([^\'\"]|Deno\.env\.toObject\(',line):dynamic.append(f'{name}:{no}')
all_doc=set(re.findall(r'\b[A-Z][A-Z0-9_]{2,}\b',book))
rows=[]
for name,locations in sorted(names.items()):
    runtime=any(p.startswith(('apps/web/src/','api/','apps/web/api/','supabase/functions/')) for p in locations)
    category='frontend' if any(p.startswith('apps/web/src/') for p in locations) else 'backend' if any(p.startswith('supabase/functions/') for p in locations) else 'tooling-or-package'
    rows.append({'name':name,'documentedByName':name in all_doc,'runtime':runtime,'category':category,'locations':locations})
configs=[]
for name in ['vercel.json','apps/web/vercel.json']:
    data=json.loads((ROOT/name).read_text());configs.append({'path':name,'keys':list(data),'buildCommand':data.get('buildCommand'),'outputDirectory':data.get('outputDirectory'),'framework':data.get('framework'),'functions':data.get('functions'),'rewrites':data.get('rewrites'),'ignoreCommand':data.get('ignoreCommand'),'shipAutoDeploymentDisabled':data.get('git',{}).get('deploymentEnabled',{}).get('codex/v4-ship-2026-11-16') is False})
paths=re.findall(r'\b(?:tools|scripts|contracts|packages|apps|supabase)/[A-Za-z0-9_./-]+',book)
path_checks=[{'path':p,'exists':(ROOT/p).exists()} for p in sorted(set(paths))]
functionNames=[]
deploy=re.search(r'supabase functions deploy\s+([\s\S]*?)--project-ref',book)
if deploy:functionNames=[p for p in deploy.group(1).replace('\\',' ').split() if re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)+',p)]
function_checks=[{'name':name,'handlerExists':(ROOT/'supabase/functions'/name/'index.ts').is_file()} for name in functionNames]
report={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'sourceSha':subprocess.check_output(['git','rev-parse','origin/codex/v4-ship-2026-11-16'],cwd=ROOT,text=True).strip(),'method':'Static identifiers only; no .env, secret stores, logins or remote writes. Dynamic access sites require manual review.','env':rows,'runbookOnlyNames':sorted(all_doc-set(names)),'dynamicAccessSites':dynamic,'paths':path_checks,'functionHandlers':function_checks,'vercelConfigs':configs,'vercelFunctionSourcePaths':[p for p in files if p.startswith(('api/','apps/web/api/'))]}
(OUT/'runbook-static.json').write_text(json.dumps(report,indent=2)+'\n')
md=['# Runbook environment-name audit','Generated by own static scanner; no secret values read or recorded.','Names absent from this runbook are candidates, not automatically required settings. Optional flags and platform-injected names must be classified.','','| Name | Area | Named in runbook | First source |','|---|---|---|---|',*[f"| `{r['name']}` | {r['category']} | {'yes' if r['documentedByName'] else 'no'} | `{r['locations'][0]}` |" for r in rows],'',f'Dynamic environment access sites: {len(dynamic)}; see runbook-static.json.','Runbook-only identifiers include shell scratch variables and external CLI variables; they are not automatically errors.']
(OUT/'ENV-NAMES.md').write_text('\n'.join(md)+'\n')
print(json.dumps({'names':len(rows),'missingRuntimeNames':[r['name'] for r in rows if r['runtime'] and not r['documentedByName']],'dynamicAccessSites':len(dynamic),'missingPaths':[r['path'] for r in path_checks if not r['exists']],'missingHandlers':[r['name'] for r in function_checks if not r['handlerExists']],'vercelFunctionFiles':len(report['vercelFunctionSourcePaths'])},ensure_ascii=False)[:2800])
